def button(text,href,light=False):return f'<a class="button{" light" if light else ""}" href="{href}">{text}<span class="arrow" aria-hidden="true">↗</span></a>'
def page(brand,title,description,body,theme,links):
    nav=''.join(f'<a href="{href}">{label}</a>' for label,href in links)
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="{'#151619' if theme=='labs' else '#eeeee7'}"><title>{title}</title><meta name="description" content="{description}"><link rel="icon" type="image/svg+xml" href="../assets/favicon.svg"><link rel="stylesheet" href="../assets/style.css"><script src="../assets/site.js" defer></script></head><body class="{theme}"><a class="skip" href="#main">Skip to content</a><header><div class="wrap nav"><a class="logo" href="./" aria-label="{brand} home">{brand}</a><nav class="navlinks" id="navigation" aria-label="Main navigation">{nav}</nav><a class="nav-cta" href="../">The gr3y family ↗</a><button class="mobile-toggle" aria-controls="navigation" aria-expanded="false">Menu</button></div></header><main id="main">{body}</main><footer class="wrap footer"><div class="footer-top"><div><a class="logo" href="./">{brand}</a><p>Independent thinking. Practical work.</p></div><nav class="footer-links" aria-label="Company sites"><a href="../capital/">gr3ycapital</a><a href="../labs/">gr3ylabs</a><a href="../support/">gr3y.io</a><a href="https://github.com/gr3ysbot-tech">GitHub ↗</a></nav></div><div class="footer-bottom"><span>© {2026} {brand}. All rights reserved.</span><span>Part of gr3ycapital.</span></div></footer></body></html>'''

capital='''<section class="wrap hero"><div class="hero-grid"><div><div class="eyebrow">Finance, with a longer view</div><h1>Good decisions.<br>Built on<br>clear thinking.</h1><p class="lede">We’re gr3ycapital. An independent company building financial software and exploring the systems behind trading and digital assets.</p>'''+button('Explore our focus','#focus')+'''</div><div class="art capital-art" role="img" aria-label="Sculptural ascending columns in muted green"><span class="art-top">GR3YCAPITAL / PERSPECTIVE 001</span><div class="steps" aria-hidden="true"><i style="--h:75px"></i><i style="--h:115px"></i><i style="--h:160px"></i><i style="--h:205px"></i><i style="--h:255px"></i></div><span class="art-label">Clarity is a compounding advantage.</span></div></div></section><div class="wrap caption"><span>Independent by design</span><span>Finance · Software · Research</span></div><section class="wrap section" id="focus"><div class="eyebrow">01 / Our focus</div><div class="section-head"><h2>Financial ideas.<br>Practical applications.</h2><p>From everyday budgets to complex markets, our interest is the same: making financial systems easier to understand and work with.</p></div><div class="rows"><div class="row"><span class="number">01</span><h3>Personal finance</h3><p>Software for a clearer picture of everyday money. Our current focus is a budgeting application, now in development.</p><span class="arrow" aria-hidden="true">↗</span></div><div class="row"><span class="number">02</span><h3>Trading & markets</h3><p>Exploring systematic approaches to markets, with an emphasis on research, disciplined processes, and useful software.</p><span class="arrow" aria-hidden="true">↗</span></div><div class="row"><span class="number">03</span><h3>Digital assets</h3><p>An ongoing interest in crypto and the financial applications being built around digital assets.</p><span class="arrow" aria-hidden="true">↗</span></div></div></section><section class="wrap section" id="building"><div class="feature"><div><div class="eyebrow">02 / In development</div><h2>A little more clarity.<br>Every single month.</h2><p>We’re developing a budget app with a straightforward ambition: help people see their money more clearly. Thoughtful tools start with everyday needs.</p><span class="tag">Budget app · In development</span></div><div><div class="budget"><div class="budget-ui"><div class="tiny">A month at a glance</div><div class="balance">Room to plan.</div><p style="font-size:12px;margin-top:6px">An early exploration of everyday finances.</p><div class="bars" aria-hidden="true"><i style="--h:42%"></i><i style="--h:61%"></i><i style="--h:52%"></i><i style="--h:76%"></i><i style="--h:69%"></i><i style="--h:89%"></i></div><div class="budget-line"><span>Less noise.</span><span>More perspective.</span></div></div></div><div class="demo-note">Illustrative design study · Not a product screenshot or financial data</div></div></div></section><section class="wrap section" id="family"><div class="eyebrow">03 / The gr3y family</div><div class="section-head"><h2>One independent spirit.<br>A few different outlets.</h2></div><div class="rows"><a class="row" href="../labs/"><span class="number">LAB</span><h3>gr3ylabs</h3><p>The software side. Remote management, Glitch, and experiments that leave room for a little fun.</p><span class="arrow">↗</span></a><a class="row" href="../support/"><span class="number">IT</span><h3>gr3y.io</h3><p>The support side. A practical approach to helping people work through technology problems.</p><span class="arrow">↗</span></a></div></section><section class="wrap section"><div class="cta"><h2>See what we’re<br>working on.</h2>'''+button('Explore our GitHub','https://github.com/gr3ysbot-tech')+'''</div><p class="demo-note">Company and product information only. This site does not offer investment advice or investment services.</p></section>'''
write('capital/index.html',page('gr3y<span>capital</span>','gr3ycapital — Finance, with a longer view','Independent financial software, trading research, and digital asset exploration. Meet gr3ycapital and the gr3y family.',capital,'capital',[('Our focus','#focus'),('In development','#building'),('The family','#family')]))

labs='''<section class="wrap hero"><div class="hero-grid"><div><div class="eyebrow">Independent software & experiments</div><h1>Serious tools.<br><em>Curious minds.</em></h1><p class="lede">A place for useful software and ideas worth trying. We’re building remote management tools, Glitch, and apps with a playful side.</p>'''+button('Inside the lab','#projects')+'''</div><div class="art labs-art" role="img" aria-label="Lime contour sphere with a fine orbital ring"><span class="art-top">GR3YLABS / AN OPEN EXPLORATION</span><div class="orbit"></div><div class="orb"></div><span class="art-label">A little curiosity goes a long way.</span></div></div></section><div class="wrap caption"><span>The experimental side of gr3ycapital</span><span>Tools / Software / Other things</span></div><section class="wrap section" id="projects"><div class="eyebrow">01 / On the workbench</div><div class="section-head"><h2>Useful by intention.<br>Unexpected by nature.</h2><p>Some projects start with a problem. Others start with “what if?” Both belong here.</p></div><div class="rows"><div class="row"><span class="number">001</span><div><h3 class="project-name"><span class="project-icon" aria-hidden="true">⌘</span>Remote management</h3><span class="tag">RMM application · In development</span></div><p>Our remote monitoring and management application. Built around the practical work of looking after technology.</p><span class="arrow" aria-hidden="true">↗</span></div><a class="row" href="https://github.com/gr3ysbot-tech/glitch"><span class="number">002</span><div><h3 class="project-name"><span class="project-icon" aria-hidden="true">/</span>Glitch</h3><span class="tag">Software project · View repository</span></div><p>A gr3ylabs project. Follow the repository to explore the work and its latest direction.</p><span class="arrow">↗</span></a><a class="row" href="https://github.com/gr3ysbot-tech/Gr3y-Tools"><span class="number">003</span><div><h3 class="project-name"><span class="project-icon" aria-hidden="true">&gt;_</span>Gr3y Tools</h3><span class="tag">Field IT utilities</span></div><p>One-line PowerShell utilities for field IT work. Small tools for the problems that turn up on the job.</p><span class="arrow">↗</span></a></div></section><section class="wrap section" id="approach"><div class="eyebrow">02 / How we think</div><div class="section-head"><h2>Make it useful.<br>Leave room to play.</h2></div><div class="notes"><article class="lab-note"><span class="number">[ 01 ]</span><h3>Start with friction.</h3><p>A repeated task. An awkward workflow. Something that should be simpler. That’s a good place to begin.</p></article><article class="lab-note"><span class="number">[ 02 ]</span><h3>Stay curious.</h3><p>Not every experiment needs a business case. Sometimes building something interesting is reason enough.</p></article><article class="lab-note"><span class="number">[ 03 ]</span><h3>Keep it practical.</h3><p>Useful software should earn its place in someone’s day. The details matter, even in the small stuff.</p></article></div></section><section class="wrap section"><div class="cta"><h2>Follow the work.<br>See where it goes.</h2>'''+button('Find us on GitHub','https://github.com/gr3ysbot-tech')+'''</div></section>'''
